import re

def run(spec: str, verilog: str, ports: list[dict]) -> dict:
    """
    Detect output ports that are assigned inside an always block but are not declared
    as logic or reg (i.e., they remain implicit wires).
    """
    # Extract output port names
    output_names = {p["name"] for p in ports if p["direction"] == "output"}

    # Find all always blocks (including @* , @(posedge ...), etc.)
    # Simple regex: always followed by optional sensitivity and then a block
    always_blocks = re.findall(r'always\s*@?\s*[^;]*?\bbegin\b(.*?)\bend\b', verilog, re.DOTALL | re.IGNORECASE)

    # Also capture always blocks that use procedural continuous assignment (assign inside always?)
    # For simplicity, we look for any assignment to an output inside the always block text.
    problematic = []
    for block in always_blocks:
        # Find assignments like out_alwaysblock = ... ; or out_alwaysblock <= ... ;
        assignments = re.findall(r'(\w+)\s*(<=|=)\s*[^;]+;', block)
        for lhs, _ in assignments:
            if lhs in output_names:
                # Check if this output is declared as logic or reg anywhere in the module
                # Look for patterns: output ... logic ... or output reg ...
                decl_pattern = rf'output\s+(?:logic\s+|reg\s+)?{re.escape(lhs)}\b'
                if not re.search(decl_pattern, verilog, re.IGNORECASE):
                    problematic.append(lhs)
                    break  # one hit per output is enough

    if problematic:
        return {
            "fired": True,
            "findings": [f"Output(s) {', '.join(sorted(set(problematic)))} assigned in always block but not declared as logic or reg"]
        }
    return {"fired": False, "findings": []}
